import{_ as s,o as a,c as i,ae as t}from"./chunks/framework.Co1PSFSm.js";const k=JSON.parse('{"title":"","description":"排查 Fresh 应用程序问题。\\n","frontmatter":{"description":"排查 Fresh 应用程序问题。\\n"},"headers":[],"relativePath":"zh/advanced/troubleshooting.md","filePath":"zh/advanced/troubleshooting.md"}'),n={name:"zh/advanced/troubleshooting.md"};function h(o,e,l,p,r,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<p>本页面包含一些技巧，帮助你在事情不如预期工作时排查你的应用。</p><h2 id="更新-deno" tabindex="-1">更新 Deno <a class="header-anchor" href="#更新-deno" aria-label="Permalink to &quot;更新 Deno&quot;">​</a></h2><p>Deno 中的 Node 兼容性层在每个 Deno 版本中都在不断接收新的改进和错误修复。你遇到的问题很可能已经被修复了。要排除这种可能性，请安装最新的 Deno 版本。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span></span></code></pre></div><h2 id="安装或重新安装依赖" tabindex="-1">安装或重新安装依赖 <a class="header-anchor" href="#安装或重新安装依赖" aria-label="Permalink to &quot;安装或重新安装依赖&quot;">​</a></h2><p>首次运行时，你可能会看到 Deno 抱怨缺少包。用以下命令安装它们：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --allow-scripts</span></span></code></pre></div><p>如果你之后遇到依赖问题，并怀疑 Deno 可能在缓存过时的包，可以通过在上述命令中添加 <code>-r</code> 来强制重新安装。</p><h2 id="更新-fresh" tabindex="-1">更新 Fresh <a class="header-anchor" href="#更新-fresh" aria-label="Permalink to &quot;更新 Fresh&quot;">​</a></h2><p>解决大多数问题的最简单方法是确保你使用的是最新版本的 <a href="https://jsr.io/@fresh/core/versions" target="_blank" rel="noreferrer">Fresh</a>。我们持续改进 Fresh，你遇到的问题很有可能已经在最新版本中解决了。</p><h2 id="不要使用-esm-sh" tabindex="-1">不要使用 esm.sh <a class="header-anchor" href="#不要使用-esm-sh" aria-label="Permalink to &quot;不要使用 esm.sh&quot;">​</a></h2><p>Fresh 1.x 严重依赖 <a href="https://esm.sh/" target="_blank" rel="noreferrer">esm.sh</a> 以便能够将 npm 包与 Fresh 一起使用。这种情况在 Fresh 2 的早期 alpha 版本中继续存在。随着迁移到 <a href="/zh/advanced/vite.html"><code>vite</code></a>，这不再是必要的，你应该直接使用 npm 中的相关 npm 包。</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &quot;imports&quot;: {</span></span>
<span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-     &quot;cowsay&quot;: &quot;https://esm.sh/cowsay&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+     &quot;cowsay&quot;: &quot;npm:cowsay@^1.6.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span></code></pre></div><blockquote><p>[info]: 不使用 <code>esm.sh</code> 可以解决你的应用中重复 Preact 版本的许多问题和隐患。如果你看到应用中浏览器中出现奇怪的 JavaScript 错误，这很可能是原因。</p></blockquote><h2 id="连接调试器" tabindex="-1">连接调试器 <a class="header-anchor" href="#连接调试器" aria-label="Permalink to &quot;连接调试器&quot;">​</a></h2><p>要连接调试器到 Deno 上的 Vite，请运行以下命令：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inspect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:vite</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或者</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deno</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --inspect-brk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:vite</span></span></code></pre></div><h2 id="调试-vite-解析" tabindex="-1">调试 Vite 解析 <a class="header-anchor" href="#调试-vite-解析" aria-label="Permalink to &quot;调试 Vite 解析&quot;">​</a></h2><p>要调试 Vite 解析问题，请使用 <code>--debug</code> 标志运行 Vite。这会在终端打印大量调试信息。</p><h2 id="调试-vite-转换" tabindex="-1">调试 Vite 转换 <a class="header-anchor" href="#调试-vite-转换" aria-label="Permalink to &quot;调试 Vite 转换&quot;">​</a></h2><p>要调试 Vite 插件转换，请使用 <a href="https://github.com/antfu-collective/vite-plugin-inspect" target="_blank" rel="noreferrer"><code>vite-plugin-inspect</code></a>。这为你提供了一个 UI，显示每个文件所有插件的所有转换。</p><h2 id="我的部署无法启动" tabindex="-1">我的部署无法启动 <a class="header-anchor" href="#我的部署无法启动" aria-label="Permalink to &quot;我的部署无法启动&quot;">​</a></h2><p>如果你的部署无法启动，请检查以下事项：</p><ol><li>确保你运行了 <code>deno task build</code>。</li><li>确保你的入口点指向生成的 <code>_fresh/server.js</code> 文件，而不是 <code>main.ts</code>。后者在 Fresh 2 中无法工作。</li></ol><p>类似 <code>ISOLATE_INTERNAL_FAILURE</code> 的错误消息可能表示上述问题，但也可能是由部署配置中的其他问题引起的。</p><h2 id="vs-code-无法找到包和-或类型" tabindex="-1">VS Code 无法找到包和/或类型 <a class="header-anchor" href="#vs-code-无法找到包和-或类型" aria-label="Permalink to &quot;VS Code 无法找到包和/或类型&quot;">​</a></h2><p>如果你在 VS Code 中看到类似 <code>Cannot find module &#39;fresh/runtime&#39;</code> 的错误，或者看到大量 TypeScript 错误，你可能没有安装 Deno 扩展。你可以在 VS Code 的扩展浏览器中轻松找到它（标识符：<code>denoland.vscode-deno</code>）。</p><p>安装并启用后，当前安装的 Deno 版本应该出现在底部状态栏中。如果这没有自动发生，你可以通过命令面板（macOS 上 Cmd+Shift+P，Windows/Linux 上 Ctrl+Shift+P）启用 Deno 扩展，并运行 <code>Deno: Enable</code>。</p><p>有关详细说明，请参阅官方 <a href="https://docs.deno.com/runtime/reference/vscode/" target="_blank" rel="noreferrer">Deno VS Code 文档</a>。</p>`,29)])])}const u=s(n,[["render",h]]);export{k as __pageData,u as default};
